export const getRestoreMatchUrl = (matchId: string,) => {




  return `/api/admin/matches/${matchId}/restore`
}

/**
 * @summary Restore a discarded match to public results and rankings
 */
export const restoreMatch = async (matchId: string,
    auditedAction: AuditedAction, options?: Parameters<typeof customFetch>[1]): Promise<AdminMatch> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<AdminMatch>(getRestoreMatchUrl(matchId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(auditedAction)
  }
);}





export const getRestoreMatchMutationKey = () => ['restoreMatch'] as const;

export const getRestoreMatchMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof restoreMatch>>, TError,RestoreMatchMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof restoreMatch>>, TError,RestoreMatchMutationVariables, TContext> => {

const mutationKey = getRestoreMatchMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof restoreMatch>>, RestoreMatchMutationVariables> = (props) => {
          const {matchId,data} = props ?? {};

          return  restoreMatch(matchId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RestoreMatchMutationResult = NonNullable<Awaited<ReturnType<typeof restoreMatch>>>
    export type RestoreMatchMutationBody = BodyType<AuditedAction>
    export type RestoreMatchMutationError = ErrorType<void>
    export type RestoreMatchMutationVariables = {matchId: string;data: BodyType<AuditedAction>}

